-- V13: Finance, payment history, exam cards and exam-card attempts.
-- Do not edit applied migrations V1-V12.

CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE grade_scale_band
    ADD CONSTRAINT ex_grade_scale_band_no_overlap
    EXCLUDE USING gist (grade_scale_id WITH =, numrange(min_mark, max_mark, '[]') WITH &&);

CREATE TABLE fee_obligation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id BIGINT NOT NULL,
    semester_id BIGINT NOT NULL,
    fee_type VARCHAR(20) NOT NULL,
    amount_due NUMERIC(12,2) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'RWF',
    counts_toward_eligibility BOOLEAN NOT NULL DEFAULT TRUE,
    status VARCHAR(12) NOT NULL DEFAULT 'ACTIVE',
    created_by BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_fee_obligation_student FOREIGN KEY (student_id) REFERENCES student(id) ON DELETE RESTRICT,
    CONSTRAINT fk_fee_obligation_semester FOREIGN KEY (semester_id) REFERENCES semester(id) ON DELETE RESTRICT,
    CONSTRAINT fk_fee_obligation_creator FOREIGN KEY (created_by) REFERENCES user_accounts(id) ON DELETE RESTRICT,
    CONSTRAINT uq_fee_obligation_student_semester_type UNIQUE (student_id, semester_id, fee_type),
    CONSTRAINT ck_fee_obligation_type CHECK (fee_type IN ('TUITION','REGISTRATION','EXAM','OTHER')),
    CONSTRAINT ck_fee_obligation_amount CHECK (amount_due > 0),
    CONSTRAINT ck_fee_obligation_currency CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_fee_obligation_status CHECK (status IN ('ACTIVE','CANCELLED'))
);
CREATE INDEX idx_fee_obligation_student_semester ON fee_obligation(student_id, semester_id);
CREATE INDEX idx_fee_obligation_semester ON fee_obligation(semester_id);
CREATE INDEX idx_fee_obligation_creator ON fee_obligation(created_by);

CREATE TABLE payment (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id BIGINT NOT NULL,
    semester_id BIGINT NOT NULL,
    fee_obligation_id BIGINT,
    amount NUMERIC(12,2) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'RWF',
    transaction_reference VARCHAR(100) NOT NULL UNIQUE,
    request_fingerprint CHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    received_at TIMESTAMPTZ NOT NULL,
    confirmed_at TIMESTAMPTZ,
    confirmed_by BIGINT,
    recorded_by BIGINT NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT fk_payment_student FOREIGN KEY (student_id) REFERENCES student(id) ON DELETE RESTRICT,
    CONSTRAINT fk_payment_semester FOREIGN KEY (semester_id) REFERENCES semester(id) ON DELETE RESTRICT,
    CONSTRAINT fk_payment_obligation FOREIGN KEY (fee_obligation_id) REFERENCES fee_obligation(id) ON DELETE RESTRICT,
    CONSTRAINT fk_payment_confirmed_by FOREIGN KEY (confirmed_by) REFERENCES user_accounts(id) ON DELETE RESTRICT,
    CONSTRAINT fk_payment_recorded_by FOREIGN KEY (recorded_by) REFERENCES user_accounts(id) ON DELETE RESTRICT,
    CONSTRAINT ck_payment_amount CHECK (amount > 0),
    CONSTRAINT ck_payment_currency CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_payment_status CHECK (status IN ('PENDING','CONFIRMED','FAILED','REVERSED')),
    CONSTRAINT ck_payment_confirmation_metadata CHECK ((status = 'CONFIRMED' AND confirmed_at IS NOT NULL) OR status <> 'CONFIRMED')
);
CREATE INDEX idx_payment_student_semester_status ON payment(student_id, semester_id, status);
CREATE INDEX idx_payment_semester ON payment(semester_id);
CREATE INDEX idx_payment_obligation ON payment(fee_obligation_id);
CREATE INDEX idx_payment_recorded_by ON payment(recorded_by);

CREATE TABLE payment_status_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payment_id BIGINT NOT NULL,
    from_status VARCHAR(20) NOT NULL,
    to_status VARCHAR(20) NOT NULL,
    changed_by BIGINT,
    reason VARCHAR(255),
    changed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_payment_history_payment FOREIGN KEY (payment_id) REFERENCES payment(id) ON DELETE RESTRICT,
    CONSTRAINT fk_payment_history_actor FOREIGN KEY (changed_by) REFERENCES user_accounts(id) ON DELETE RESTRICT,
    CONSTRAINT ck_payment_history_status CHECK (from_status IN ('PENDING','CONFIRMED','FAILED','REVERSED') AND to_status IN ('PENDING','CONFIRMED','FAILED','REVERSED')),
    CONSTRAINT ck_payment_history_transition CHECK (from_status <> to_status)
);
CREATE INDEX idx_payment_history_payment ON payment_status_history(payment_id, changed_at DESC);

CREATE OR REPLACE FUNCTION prevent_payment_history_mutation() RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'payment_status_history is append-only';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_payment_history_no_mutation
    BEFORE UPDATE OR DELETE ON payment_status_history
    FOR EACH ROW EXECUTE FUNCTION prevent_payment_history_mutation();

CREATE OR REPLACE FUNCTION protect_payment_immutable_fields() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'payments cannot be deleted';
    END IF;
    IF NEW.student_id IS DISTINCT FROM OLD.student_id
       OR NEW.semester_id IS DISTINCT FROM OLD.semester_id
       OR NEW.fee_obligation_id IS DISTINCT FROM OLD.fee_obligation_id
       OR NEW.amount IS DISTINCT FROM OLD.amount
       OR NEW.currency IS DISTINCT FROM OLD.currency
       OR NEW.transaction_reference IS DISTINCT FROM OLD.transaction_reference
       OR NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint
       OR NEW.received_at IS DISTINCT FROM OLD.received_at
       OR NEW.recorded_by IS DISTINCT FROM OLD.recorded_by THEN
        RAISE EXCEPTION 'payment identity and amount fields are immutable';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_payment_immutable_fields
    BEFORE UPDATE OR DELETE ON payment
    FOR EACH ROW EXECUTE FUNCTION protect_payment_immutable_fields();

CREATE OR REPLACE FUNCTION protect_fee_obligation_immutable_fields() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'fee obligations cannot be deleted';
    END IF;
    IF NEW.student_id IS DISTINCT FROM OLD.student_id
       OR NEW.semester_id IS DISTINCT FROM OLD.semester_id
       OR NEW.fee_type IS DISTINCT FROM OLD.fee_type
       OR NEW.amount_due IS DISTINCT FROM OLD.amount_due
       OR NEW.currency IS DISTINCT FROM OLD.currency
       OR NEW.counts_toward_eligibility IS DISTINCT FROM OLD.counts_toward_eligibility
       OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'fee obligation details are immutable; cancel and recreate instead';
    END IF;
    IF OLD.status = 'CANCELLED' AND NEW.status <> 'CANCELLED' THEN
        RAISE EXCEPTION 'cancelled fee obligations cannot be reactivated';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_fee_obligation_immutable_fields
    BEFORE UPDATE OR DELETE ON fee_obligation
    FOR EACH ROW EXECUTE FUNCTION protect_fee_obligation_immutable_fields();

CREATE TABLE exam_card (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    course_registration_id BIGINT NOT NULL UNIQUE,
    student_id BIGINT NOT NULL,
    semester_id BIGINT NOT NULL,
    card_number VARCHAR(50) NOT NULL UNIQUE,
    status VARCHAR(10) NOT NULL DEFAULT 'ISSUED',
    issued_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    requested_by BIGINT NOT NULL,
    CONSTRAINT fk_exam_card_registration FOREIGN KEY (course_registration_id) REFERENCES course_registrations(id) ON DELETE RESTRICT,
    CONSTRAINT fk_exam_card_student FOREIGN KEY (student_id) REFERENCES student(id) ON DELETE RESTRICT,
    CONSTRAINT fk_exam_card_semester FOREIGN KEY (semester_id) REFERENCES semester(id) ON DELETE RESTRICT,
    CONSTRAINT fk_exam_card_requester FOREIGN KEY (requested_by) REFERENCES user_accounts(id) ON DELETE RESTRICT,
    CONSTRAINT ck_exam_card_status CHECK (status IN ('ISSUED','REVOKED'))
);
CREATE INDEX idx_exam_card_student_semester ON exam_card(student_id, semester_id);
CREATE INDEX idx_exam_card_semester ON exam_card(semester_id);

CREATE TABLE exam_card_attempt (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id BIGINT NOT NULL,
    course_registration_id BIGINT,
    exam_card_id BIGINT,
    outcome VARCHAR(10) NOT NULL,
    refusal_reason VARCHAR(40),
    requested_by BIGINT NOT NULL,
    ip_address VARCHAR(45),
    requested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_exam_attempt_student FOREIGN KEY (student_id) REFERENCES student(id) ON DELETE RESTRICT,
    CONSTRAINT fk_exam_attempt_registration FOREIGN KEY (course_registration_id) REFERENCES course_registrations(id) ON DELETE RESTRICT,
    CONSTRAINT fk_exam_attempt_card FOREIGN KEY (exam_card_id) REFERENCES exam_card(id) ON DELETE RESTRICT,
    CONSTRAINT fk_exam_attempt_requester FOREIGN KEY (requested_by) REFERENCES user_accounts(id) ON DELETE RESTRICT,
    CONSTRAINT ck_exam_attempt_outcome CHECK (outcome IN ('ISSUED','REFUSED')),
    CONSTRAINT ck_exam_attempt_reason CHECK ((outcome = 'ISSUED' AND exam_card_id IS NOT NULL AND refusal_reason IS NULL) OR (outcome = 'REFUSED' AND refusal_reason IS NOT NULL AND length(trim(refusal_reason)) > 0))
);
CREATE INDEX idx_exam_attempt_student_requested ON exam_card_attempt(student_id, requested_at DESC);
CREATE INDEX idx_exam_attempt_registration ON exam_card_attempt(course_registration_id);
CREATE INDEX idx_exam_attempt_card ON exam_card_attempt(exam_card_id);

CREATE OR REPLACE FUNCTION prevent_exam_card_attempt_mutation() RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'exam_card_attempt is append-only';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_exam_attempt_no_mutation
    BEFORE UPDATE OR DELETE ON exam_card_attempt
    FOR EACH ROW EXECUTE FUNCTION prevent_exam_card_attempt_mutation();
